544          public boolean overloadOk() {
545  
546              // exclusion is good.
547              if (distinct) return true;
548  
549              // non-ground types need exclusion
550              if (sawSymbolic1 || sawSymbolic2 || unrelated != -1) {
551                  return false;
552              }
553  
554              // meet rule
555              if (p1better >= 0 && p2better >= 0 && !meetOk) return false;
556  
557              // neither is better, not a functional method
558              if (p1better < 0 && p2better < 0 && selfIndex < 0) return false;
559  
560              if (result1Subtype2Failure || result2Subtype1Failure) return false;
561  
562              return true;
563          }
